#!/usr/bin/env bash
# Refuse launch unless the macOS retrodeck folder is genuinely shared and writable.
set -Eeuo pipefail
source "$(dirname "$0")/common.sh"
need_macos
[[ ! -L "$F4M_SHARE" ]] || fail 'retrodeck must be a real directory, not a symlink.'
mkdir -p "$F4M_SHARE" # no subdirectories created
log "Using host RetroDECK folder: $F4M_SHARE"
# Device tag 'share' is generated by UTM QEMU VirtFS setting in Sharing.
if ! ssh_guest 'bash -s' <<'GUEST'
set -Eeuo pipefail
mount_dir=/home/flatpak/retrodeck
if mountpoint -q "$mount_dir"; then
  [[ "$(findmnt -n -o FSTYPE --target "$mount_dir")" == 9p ]] || { echo 'Existing mount is not VirtFS/9p' >&2; exit 1; }
else
  if [[ -d "$mount_dir" ]] && [[ -n "$(find "$mount_dir" -mindepth 1 -maxdepth 1 -print -quit)" ]]; then
    echo "Existing data in $mount_dir: refusing to mount over it. Back up/migrate manually." >&2
    exit 1
  fi
  sudo mkdir -p "$mount_dir"
  sudo mount -t 9p -o trans=virtio,version=9p2000.L,rw share "$mount_dir" || {
    echo 'VirtFS mount failed. Run scripts/configure-retrodeck-share.sh on macOS and retry.' >&2
    exit 1
  }
fi
mountpoint -q "$mount_dir" || exit 1
if ! sudo -u flatpak sh -c 'test -w /home/flatpak/retrodeck'; then
  echo 'Mounted share not writable as flatpak; attempting non-recursive mount-root ownership repair.' >&2
  sudo chown flatpak:flatpak "$mount_dir" || { echo 'Unable to correct VirtFS root ownership' >&2; exit 1; }
  sudo -u flatpak sh -c 'test -w /home/flatpak/retrodeck' || { echo 'VirtFS root still not writable as flatpak after chown' >&2; exit 1; }
fi
if ! grep -Eq '^share[[:space:]]+/home/flatpak/retrodeck[[:space:]]+9p[[:space:]]' /etc/fstab; then
  echo 'share /home/flatpak/retrodeck 9p trans=virtio,version=9p2000.L,rw,nofail,x-systemd.device-timeout=10s 0 0' | sudo tee -a /etc/fstab >/dev/null
fi
GUEST
then
  fail "Share configuration failed. Stop UTM VM; configure UTM > VM Settings > Sharing > VirtFS > select $F4M_SHARE; then start VM and rerun."
fi
# Prove both directions reach the *same* directory, with a temporary unique file.
token="f4m-$$-$(date +%s)"
printf '%s' "$token" > "$F4M_SHARE/.f4m-host-check"
if ! ssh_guest "test \"\$(cat /home/flatpak/retrodeck/.f4m-host-check)\" = '$token' && printf '%s' '$token' > /home/flatpak/retrodeck/.f4m-guest-check"; then
  rm -f "$F4M_SHARE/.f4m-host-check" "$F4M_SHARE/.f4m-guest-check"
  fail 'The guest mount does not point to the expected host directory, or is not writable.'
fi
if [[ "$(cat "$F4M_SHARE/.f4m-guest-check" 2>/dev/null || true)" != "$token" ]]; then
  rm -f "$F4M_SHARE/.f4m-host-check" "$F4M_SHARE/.f4m-guest-check"
  fail 'Guest writes did not arrive on the host shared folder.'
fi
rm -f "$F4M_SHARE/.f4m-host-check" "$F4M_SHARE/.f4m-guest-check"
log 'RetroDECK 9p share verified in both directions.'
